// AgentsActivities describes available worker activities
type AgentsActivities interface {
	// agent.v1.Agents.CallModel implements a(n) agent.v1.CallModel activity definition
	CallModel(ctx context.Context, req *CallModelInput) (*CallModelOutput, error)
}

// RegisterAgentsActivities registers activities with a worker
func RegisterAgentsActivities(r worker.ActivityRegistry, activities AgentsActivities) {
	RegisterCallModelActivity(r, activities.CallModel)
}

// RegisterCallModelActivity registers a agent.v1.CallModel activity
func RegisterCallModelActivity(r worker.ActivityRegistry, fn func(context.Context, *CallModelInput) (*CallModelOutput, error)) {
	r.RegisterActivityWithOptions(fn, activity.RegisterOptions{
		Name: CallModelActivityName,
	})
}

// CallModelFuture describes a(n) agent.v1.CallModel activity execution
type CallModelFuture struct {
	Future workflow.Future
}

// Get blocks on the activity's completion, returning the response
func (f *CallModelFuture) Get(ctx workflow.Context) (*CallModelOutput, error) {
	var resp CallModelOutput
	if err := f.Future.Get(ctx, &resp); err != nil {
		return nil, err
	}
	return &resp, nil
}

// Select adds the activity's completion to the selector, callback can be nil
func (f *CallModelFuture) Select(sel workflow.Selector, fn func(*CallModelFuture)) workflow.Selector {
	return sel.AddFuture(f.Future, func(workflow.Future) {
		if fn != nil {
			fn(f)
		}
	})
}

// CallModel executes a(n) agent.v1.CallModel activity
func CallModel(ctx workflow.Context, req *CallModelInput, options ...*CallModelActivityOptions) (*CallModelOutput, error) {
	return CallModelAsync(ctx, req, options...).Get(ctx)
}

// CallModelAsync executes a(n) agent.v1.CallModel activity (asynchronously)
func CallModelAsync(ctx workflow.Context, req *CallModelInput, options ...*CallModelActivityOptions) *CallModelFuture {
	var o *CallModelActivityOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewCallModelActivityOptions()
	}
	var err error
	if ctx, err = o.Build(ctx); err != nil {
		errF, errS := workflow.NewFuture(ctx)
		errS.SetError(err)
		return &CallModelFuture{Future: errF}
	}
	activity := CallModelActivityName
	if o.dc != nil {
		ctx = workflow.WithDataConverter(ctx, o.dc)
	}
	future := &CallModelFuture{Future: workflow.ExecuteActivity(ctx, activity, req)}
	return future
}

// CallModelLocal executes a(n) agent.v1.CallModel activity (locally)
func CallModelLocal(ctx workflow.Context, req *CallModelInput, options ...*CallModelLocalActivityOptions) (*CallModelOutput, error) {
	return CallModelLocalAsync(ctx, req, options...).Get(ctx)
}

// CallModelLocalAsync executes a(n) agent.v1.CallModel activity (asynchronously, locally)
func CallModelLocalAsync(ctx workflow.Context, req *CallModelInput, options ...*CallModelLocalActivityOptions) *CallModelFuture {
	var o *CallModelLocalActivityOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewCallModelLocalActivityOptions()
	}
	var err error
	if ctx, err = o.Build(ctx); err != nil {
		errF, errS := workflow.NewFuture(ctx)
		errS.SetError(err)
		return &CallModelFuture{Future: errF}
	}
	var activity any
	if o.fn != nil {
		activity = o.fn
	} else {
		activity = CallModelActivityName
	}
	if o.dc != nil {
		ctx = workflow.WithDataConverter(ctx, o.dc)
	}
	future := &CallModelFuture{Future: workflow.ExecuteLocalActivity(ctx, activity, req)}
	return future
}

// CallModelActivityOptions provides configuration for a(n) agent.v1.CallModel activity
type CallModelActivityOptions struct {
	options                workflow.ActivityOptions
	retryPolicy            *temporal.RetryPolicy
	scheduleToCloseTimeout *time.Duration
	startToCloseTimeout    *time.Duration
	dc                     converter.DataConverter
	heartbeatTimeout       *time.Duration
	scheduleToStartTimeout *time.Duration
	taskQueue              *string
	waitForCancellation    *bool
}

// NewCallModelActivityOptions initializes a new CallModelActivityOptions value
func NewCallModelActivityOptions() *CallModelActivityOptions {
	return &CallModelActivityOptions{}
}

// Build initializes a workflow.Context with appropriate ActivityOptions values derived from schema defaults and any user-defined overrides
func (o *CallModelActivityOptions) Build(ctx workflow.Context) (workflow.Context, error) {
	opts := o.options
	if v := o.heartbeatTimeout; v != nil {
		opts.HeartbeatTimeout = *v
	}
	if v := o.retryPolicy; v != nil {
		opts.RetryPolicy = v
	} else if opts.RetryPolicy == nil {
		opts.RetryPolicy = &temporal.RetryPolicy{MaximumAttempts: int32(3)}
	}
	if v := o.scheduleToCloseTimeout; v != nil {
		opts.ScheduleToCloseTimeout = *v
	}
	if v := o.scheduleToStartTimeout; v != nil {
		opts.ScheduleToStartTimeout = *v
	}
	if v := o.startToCloseTimeout; v != nil {
		opts.StartToCloseTimeout = *v
	} else if opts.StartToCloseTimeout == 0 {
		opts.StartToCloseTimeout = 600000000000 // 10 minutes
	}
	if v := o.taskQueue; v != nil {
		opts.TaskQueue = *v
	} else if opts.TaskQueue == "" {
		opts.TaskQueue = AgentsTaskQueue
	}
	if v := o.waitForCancellation; v != nil {
		opts.WaitForCancellation = *v
	}
	return workflow.WithActivityOptions(ctx, opts), nil
}

// WithActivityOptions specifies an initial ActivityOptions value to which defaults will be applied
func (o *CallModelActivityOptions) WithActivityOptions(options workflow.ActivityOptions) *CallModelActivityOptions {
	o.options = options
	return o
}

