// TestClient provides a testsuite-compatible Client
type TestAgentsClient struct {
	env       *testsuite.TestWorkflowEnvironment
	workflows AgentsWorkflows
}

var _ AgentsClient = &TestAgentsClient{}

// NewTestAgentsClient initializes a new TestAgentsClient value
func NewTestAgentsClient(env *testsuite.TestWorkflowEnvironment, workflows AgentsWorkflows, activities AgentsActivities) *TestAgentsClient {
	if workflows != nil {
		RegisterAgentsWorkflows(env, workflows)
	}
	if activities != nil {
		RegisterAgentsActivities(env, activities)
	}
	return &TestAgentsClient{env, workflows}
}

// Agent executes a(n) agent.v1.Agent workflow in the test environment
func (c *TestAgentsClient) Agent(ctx context.Context, req *AgentInput, opts ...*AgentOptions) (*AgentOutput, error) {
	run, err := c.AgentAsync(ctx, req, opts...)
	if err != nil {
		return nil, err
	}
	return run.Get(ctx)
}

// AgentAsync executes a(n) agent.v1.Agent workflow in the test environment
func (c *TestAgentsClient) AgentAsync(ctx context.Context, req *AgentInput, options ...*AgentOptions) (AgentRun, error) {
	var o *AgentOptions
	if len(options) > 0 && options[0] != nil {
		o = options[0]
	} else {
		o = NewAgentOptions()
	}
	opts, err := o.Build(req.ProtoReflect())
	if err != nil {
		return nil, fmt.Errorf("error initializing client.StartWorkflowOptions: %w", err)
	}
	return &testAgentRun{client: c, env: c.env, opts: &opts, req: req, workflows: c.workflows}, nil
}

// GetAgent is a noop
func (c *TestAgentsClient) GetAgent(ctx context.Context, workflowID string, runID string) AgentRun {
	return &testAgentRun{env: c.env, workflows: c.workflows}
}

// CancelWorkflow requests cancellation of an existing workflow execution
func (c *TestAgentsClient) CancelWorkflow(ctx context.Context, workflowID string, runID string) error {
	c.env.CancelWorkflow()
	return nil
}

// TerminateWorkflow terminates an existing workflow execution
func (c *TestAgentsClient) TerminateWorkflow(ctx context.Context, workflowID string, runID string, reason string, details ...interface{}) error {
	return c.CancelWorkflow(ctx, workflowID, runID)
}

// SandboxAssign executes a agent.v1.Agents.SandboxAssign signal
func (c *TestAgentsClient) SandboxAssign(ctx context.Context, workflowID string, runID string, req *SandboxAssignInput) error {
	c.env.SignalWorkflow(SandboxAssignSignalName, req)
	return nil
}

// SandboxLeaseDeny executes a agent.v1.Agents.SandboxLeaseDeny signal
func (c *TestAgentsClient) SandboxLeaseDeny(ctx context.Context, workflowID string, runID string, req *SandboxLeaseDenyInput) error {
	c.env.SignalWorkflow(SandboxLeaseDenySignalName, req)
	return nil
}

// SandboxLeaseGrant executes a agent.v1.Agents.SandboxLeaseGrant signal
